#!/usr/bin/env bash
# Generated by scripts/installer/build.mjs from scripts/installer/sh/; edit the parts, then run bun scripts/installer/build.mjs.
# Install the snipset terminal companion on Linux x64 from public release
# assets, then set it up the way a working station looks: a standalone
# database, shell integration (helpers, completion, TAB expansion, Enter
# trigger), and generated trigger shims. Every setup step is idempotent and
# strictly opt-out; only the binary install itself is mandatory.
set -euo pipefail
if ((BASH_VERSINFO[0] < 4 || (BASH_VERSINFO[0] == 4 && BASH_VERSINFO[1] < 4))); then
  # mapfile and empty arrays under set -u need 4.4; note and die are not defined yet.
  printf 'install.sh: bash 4.4 or newer is required; this is bash %s\n' "${BASH_VERSION}" >&2
  exit 1
fi
n_drift=0
n_kept=0
n_removed=0
n_fail=0
note() { printf 'install.sh: %s\n' "$1" >&2; }
die() {
  note "$1"
  exit "${2:-1}"
}
report() {
  printf '[%s] %s: %s\n' "$1" "$2" "$3"
  # Plain assignments: ((n++)) returns 1 when n was 0, which set -e treats as failure.
  case "$1" in
    DRIFT|MISSING) n_drift=$((n_drift + 1)) ;;
    KEEP) n_kept=$((n_kept + 1)) ;;
    REMOVED) n_removed=$((n_removed + 1)) ;;
    FAIL) n_fail=$((n_fail + 1)) ;;
  esac
}
act() {
  local desc="$1"
  shift
  if ((dry_run)); then
    printf '[DRY] %s\n' "$desc"
    return 0
  fi
  "$@"
}
rewrite_backup=""
rewrite_restored=1
# Replaces FILE's content with NEWFILE's in place, so FILE and a symlink to it stay
# where they are. Returns 2 on any failure; rewrite_backup then names the kept copy
# of the old content and rewrite_restored says whether FILE still matches it.
rewrite_file() {
  local file="$1" new="$2" bak="${1}.snipset-bak.$$"
  rewrite_backup=""
  rewrite_restored=1
  if ! cp -- "$file" "$bak" 2>/dev/null || ! cmp -s -- "$file" "$bak"; then
    rm -f -- "$bak" "$new"
    return 2
  fi
  if cat -- "$new" 2>/dev/null > "$file" && cmp -s -- "$new" "$file"; then
    rm -f -- "$bak" "$new"
    return 0
  fi
  cat -- "$bak" 2>/dev/null > "$file" || true
  cmp -s -- "$bak" "$file" || rewrite_restored=0
  rewrite_backup="$bak"
  rm -f -- "$new"
  return 2
}
# Stages CMD's output beside FILE, never in TMPDIR, which may be missing or full,
# then hands it to rewrite_file. Returns 2 before FILE is touched when staging fails.
rewrite_from() {
  local file="$1" new
  shift
  rewrite_backup=""
  rewrite_restored=1
  new="$(mktemp "${file}.snipset-new.XXXXXX" 2>/dev/null)" || return 2
  if ! "$@" > "$new"; then
    rm -f -- "$new"
    return 2
  fi
  rewrite_file "$file" "$new"
}
rewrite_fail() {
  if [[ -z "$rewrite_backup" ]]; then
    report FAIL "$1" "$2 left unchanged"
  elif ((rewrite_restored)); then
    report FAIL "$1" "$2 left unchanged (backup: ${rewrite_backup})"
  else
    report FAIL "$1" "$2 could not be restored (backup: ${rewrite_backup})"
  fi
}
print_usage() {
  cat <<'EOF'
Usage: install.sh [--version VERSION] [--install-dir DIR] [--add-path]
                  [--share-dir DIR] [--db PATH] [--bashrc PATH]
                  [--no-init] [--no-shell] [--no-shims] [--with-mcp]
                  [--with-mcp=LIST] [--from DIR] [--dry-run]
                  [--check | --update | --uninstall]
                  [--help]

  --version VERSION  Release to install (default: latest).
  --install-dir DIR  Binary destination (default: ~/.local/bin).
  --add-path         Add the install dir to PATH for bash, zsh, and fish (writes <share-dir>/env).
  --share-dir DIR    Shell bundle destination (default: ~/.local/share/snipset).
  --db PATH          Database for init/shims (default: the CLI default).
  --bashrc PATH      Shell startup file for integration (default: ~/.bashrc).
  --no-init          Skip creating the standalone database.
  --no-shell         Skip shell integration.
  --no-shims         Skip generating trigger shims.
  --with-mcp         Write ~/.config/opencode/opencode.json if absent.
                     An existing entry is never changed.
  --with-mcp=LIST    Register MCP for LIST: claude,codex,gemini,opencode,cursor,vscode or all.
                     An existing entry is never changed.
  --from DIR         Install from SHA256SUMS and the archive in DIR (no download).
  --dry-run          Print every step and write nothing.
  --check            Report drift of an install made with the same flags (exit 1 on drift).
  --update           Install the latest (or --version) release over the current one.
  --uninstall        Remove what an install with the same flags wrote, including MCP
                     entries for the --with-mcp list you pass (the same list as the
                     install). Never removes the database.
  --help, -h         Show this help and exit.
EOF
}
usage() {
  print_usage >&2
  exit 2
}
parse_args() {
  local raw id wanted known=" claude codex gemini opencode cursor vscode " path_value
  local -a ids
  repo="belajarcarabelajar/snipset-cli"
  version=""
  install_dir="${HOME}/.local/bin"
  share_dir="${HOME}/.local/share/snipset"
  bashrc="${HOME}/.bashrc"
  db=""
  add_path=0
  do_init=1
  do_shell=1
  do_shims=1
  mcp_list=""
  from_dir=""
  mode="install"
  dry_run=0
  base_url="${SNIPSET_RELEASE_BASE_URL:-https://github.com/${repo}/releases/download}"
  wanted=" "
  while (($#)); do
    case "$1" in
      --version) [[ $# -ge 2 ]] || usage; version="$2"; shift 2 ;;
      --install-dir) [[ $# -ge 2 ]] || usage; install_dir="$2"; shift 2 ;;
      --share-dir) [[ $# -ge 2 ]] || usage; share_dir="$2"; shift 2 ;;
      --db) [[ $# -ge 2 ]] || usage; db="$2"; shift 2 ;;
      --bashrc) [[ $# -ge 2 ]] || usage; bashrc="$2"; shift 2 ;;
      --from) [[ $# -ge 2 ]] || usage; from_dir="$2"; shift 2 ;;
      --add-path) add_path=1; shift ;;
      --no-init) do_init=0; shift ;;
      --no-shell) do_shell=0; shift ;;
      --no-shims) do_shims=0; shift ;;
      --with-mcp|--with-mcp=) wanted+="opencode "; shift ;;
      --with-mcp=*)
        raw="${1#--with-mcp=}"
        # read -a drops a trailing empty field, so check for empty ids first.
        [[ ",${raw}," != *,,* ]] || usage
        IFS=',' read -r -a ids <<< "$raw"
        for id in "${ids[@]}"; do
          if [[ "$id" == all ]]; then
            wanted+="${known# }"
          elif [[ "$known" == *" ${id} "* ]]; then
            wanted+="${id} "
          else
            usage
          fi
        done
        shift ;;
      --dry-run) dry_run=1; shift ;;
      --check|--update|--uninstall)
        [[ "$mode" == install ]] || usage
        mode="${1#--}"
        shift ;;
      --help|-h) print_usage; exit 0 ;;
      *) usage ;;
    esac
  done
  # Canonical order without duplicates, whatever order or repeats the flags used.
  for id in $known; do
    [[ "$wanted" != *" ${id} "* ]] || mcp_list+="${mcp_list:+ }${id}"
  done
  for path_value in "$install_dir" "$share_dir" "$bashrc" "$db" "$from_dir"; do
    # shellcheck disable=SC1003 # '\' is a literal backslash pattern, not a quote escape
    case "$path_value" in
      *$'\n'*|*$'\r'*|*'"'*|*'`'*|*'\'*|*'$'*)
        die 'path must not contain newline or shell-special characters (" ` \ $)' 2 ;;
    esac
  done
}
platform_require() {
  local os cpu glibc major minor
  os="$(uname -s 2>/dev/null || true)"
  case "$os" in
    Linux) ;;
    Darwin) die 'no macOS build is published yet; see "Known limits" in README.md' ;;
    *) die "unsupported OS ${os:-unknown}" ;;
  esac
  cpu="$(uname -m 2>/dev/null || true)"
  case "$cpu" in
    x86_64|amd64) ;;
    aarch64|arm64) die 'no ARM build is published yet; see "Known limits" in README.md' ;;
    *) die "unsupported CPU ${cpu:-unknown}" ;;
  esac
  # musl ldd prints its banner to stderr and exits 1.
  if command -v ldd >/dev/null 2>&1 && [[ "$(ldd --version 2>&1 || true)" == *musl* ]]; then
    die 'musl libc (for example Alpine) is not supported; the build needs glibc 2.34 or newer'
  fi
  glibc="$(platform_glibc_version)"
  if [[ -z "$glibc" ]]; then
    note 'could not determine the glibc version; the build needs glibc 2.34 or newer, continuing'
  else
    major="${glibc%%.*}"
    minor="${glibc#*.}"
    if ((10#$major < 2 || (10#$major == 2 && 10#$minor < 34))); then
      die "glibc ${glibc} is too old; the build needs glibc 2.34 or newer"
    fi
  fi
  target="x86_64-unknown-linux-gnu"
}
# Prints MAJOR.MINOR, or nothing when neither getconf nor ldd reports a version.
platform_glibc_version() {
  local raw=""
  if command -v getconf >/dev/null 2>&1; then
    raw="$(getconf GNU_LIBC_VERSION 2>/dev/null || true)"
    raw="${raw##* }"
  fi
  if [[ ! "$raw" =~ ^[0-9]+\.[0-9]+ ]] && command -v ldd >/dev/null 2>&1; then
    raw="$(ldd --version 2>/dev/null | head -n 1 || true)"
    raw="${raw##* }"
  fi
  if [[ "$raw" =~ ^([0-9]+)\.([0-9]+) ]]; then
    printf '%s.%s\n' "${BASH_REMATCH[1]}" "${BASH_REMATCH[2]}"
  fi
}
fetch_tools_require() {
  command -v tar >/dev/null || die 'tar is required'
  if [[ -z "$from_dir" ]] && ! command -v curl >/dev/null && ! command -v wget >/dev/null; then
    die 'curl or wget is required'
  fi
  if [[ -z "$from_dir" && "$base_url" != https://* ]]; then
    die "SNIPSET_RELEASE_BASE_URL must start with https:// (got ${base_url}); use --from DIR for local files"
  fi
  command -v sha256sum >/dev/null || command -v shasum >/dev/null || command -v openssl >/dev/null ||
    die 'sha256sum, shasum, or openssl is required'
}
fetch_get() {
  local curl_opts=(--proto '=https' --proto-redir '=https' --retry 3 --connect-timeout 15 --speed-limit 1024 --speed-time 60)
  if command -v curl >/dev/null; then
    curl -fsSL "${curl_opts[@]}" "$1" -o "$2"
  else
    wget --tries=3 --timeout=15 -q -O "$2" "$1"
  fi
}
fetch_text() {
  local curl_opts=(--proto '=https' --proto-redir '=https' --retry 3 --connect-timeout 15 --speed-limit 1024 --speed-time 60)
  if command -v curl >/dev/null; then
    curl -fsSL "${curl_opts[@]}" "$1"
  else
    wget --tries=3 --timeout=15 -qO- "$1"
  fi
}
sha256_of() {
  if command -v sha256sum >/dev/null; then
    sha256sum "$1"
  elif command -v shasum >/dev/null; then
    shasum -a 256 "$1"
  else
    openssl dgst -sha256 -r "$1"
  fi | awk '{print $1}'
}
fetch_from_version() {
  local sums="${from_dir}/SHA256SUMS" name
  local -a names=()
  [[ -f "$sums" ]] || die "${sums} is missing"
  while IFS= read -r name; do
    if [[ "$name" == snipset-cli-v*-"${target}.tar.gz" ]]; then
      names+=("$name")
    fi
  done < <(awk '{ fname=$2; sub(/^[*]/, "", fname); print fname }' "$sums" | sort -u)
  ((${#names[@]} == 1)) ||
    die "expected one snipset-cli-v<VERSION>-${target}.tar.gz in ${sums}, found ${#names[@]}; pass --version"
  version="${names[0]#snipset-cli-}"
  version="${version%-"${target}".tar.gz}"
  [[ "$version" =~ ^v[0-9]+\.[0-9]+\.[0-9]+([.-][0-9A-Za-z.-]+)?$ ]] || die "invalid version in ${sums}"
}
fetch_resolve_version() {
  if [[ -z "$version" && -n "$from_dir" ]]; then
    fetch_from_version
  elif [[ -z "$version" ]]; then
    version="$(fetch_text "https://api.github.com/repos/${repo}/releases/latest" | sed -n 's/.*"tag_name"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' | head -n 1)"
    [[ "$version" =~ ^v[0-9]+\.[0-9]+\.[0-9]+([.-][0-9A-Za-z.-]+)?$ ]] || die 'release version was not found'
  else
    [[ "$version" =~ ^v?[0-9]+\.[0-9]+\.[0-9]+([.-][0-9A-Za-z.-]+)?$ ]] || die 'invalid version' 2
    [[ "$version" == v* ]] || version="v${version}"
  fi
  archive="snipset-cli-${version}-${target}.tar.gz"
  release_url="${base_url}/${version}"
}
fetch_release() {
  local name
  if [[ -n "$from_dir" ]]; then
    for name in SHA256SUMS "$archive"; do
      [[ -f "${from_dir}/${name}" ]] || die "${from_dir}/${name} is missing"
      cp "${from_dir}/${name}" "${1}/${name}"
    done
    return 0
  fi
  fetch_get "${release_url}/SHA256SUMS" "${1}/SHA256SUMS"
  fetch_get "${release_url}/${archive}" "${1}/${archive}"
}
binary_verify() {
  local dir="$1" expected actual entry names verbose
  expected="$(awk -v name="$archive" '{ fname=$2; sub(/^[*]/, "", fname); if (fname == name) { print $1 } }' "${dir}/SHA256SUMS")"
  [[ "$expected" =~ ^[[:xdigit:]]{64}$ ]] || die 'checksum entry missing'
  actual="$(sha256_of "${dir}/${archive}")"
  [[ "$actual" == "$expected" ]] || die 'checksum mismatch'
  # Captured, not streamed: a tar that fails to list must stop the install, not read as an empty archive.
  names="$(tar --quoting-style=escape -tzf "${dir}/${archive}")" || die 'cannot list the archive'
  verbose="$(tar --quoting-style=escape -tvzf "${dir}/${archive}")" || die 'cannot list the archive'
  while IFS= read -r entry; do
    [[ "$entry" != *$'\n'* ]] || die 'unsafe archive entry'
    [[ "$entry" != -* && "$entry" != .-* && "$entry" != /* && "$entry" != ../* && "$entry" != */../* ]] || die 'unsafe archive entry'
  done <<< "$names"
  [[ $'\n'"$verbose" != *$'\n'l* ]] || die 'symlinks are not allowed in release archives'
}
binary_stage() {
  mkdir -p "$install_dir"
  stage="$(mktemp -d "${install_dir}/.snipset-stage.XXXXXX")"
  # As root, tar would otherwise keep the packer's uid and mode bits.
  tar --no-same-owner --no-same-permissions -xzf "${1}/${archive}" -C "$stage"
  [[ -f "${stage}/snipset" && -x "${stage}/snipset" ]] || { note 'archive has no executable snipset'; rm -rf "$stage"; exit 1; }
  chmod 755 "${stage}/snipset"
}
binary_run_version() {
  if command -v timeout >/dev/null 2>&1; then
    timeout 30 "$1" --version
  else
    "$1" --version
  fi
}
binary_smoke() {
  local out line rc=0
  out="$(binary_run_version "${stage}/snipset" 2>&1)" || rc=$?
  if ((rc == 0)) && [[ "$out" == "snipset "* ]]; then
    return 0
  fi
  note "the downloaded snipset failed to run (exit ${rc}):"
  while IFS= read -r line; do
    note "  ${line}"
  done <<< "$out"
  if command -v ldd >/dev/null 2>&1; then
    while IFS= read -r line; do
      [[ "$line" != *'not found'* ]] || note "  ldd: ${line#"${line%%[![:space:]]*}"}"
    done < <(ldd "${stage}/snipset" 2>&1 || true)
  fi
  die "install aborted before replacing ${install_dir}/snipset"
}
# mv -f would overwrite a file the user owns (or a link's target slot), and
# uninstall would later delete it as ours.
binary_refuse_foreign() {
  local target="$1" check="$2"
  [[ -e "$target" || -L "$target" ]] || return 0
  [[ ! -L "$target" && -f "$target" ]] && "$check" "$target" && return 0
  die "${target} exists and is not a snipset install; move it aside or pass --install-dir"
}
binary_place() {
  # The shell bundle (shell/snipset.sh, shell/completion.bash, shell/tab.sh,
  # shell/snipset-shims.sh) ships with newer releases. Older archives carry the
  # binary only; setup steps below degrade to a binary-only install.
  has_shell=0
  if [[ -f "${stage}/shell/snipset.sh" && -f "${stage}/shell/completion.bash" && -f "${stage}/shell/tab.sh" && -f "${stage}/shell/snipset-shims.sh" ]]; then
    has_shell=1
  fi
  # Both targets are checked before either move, so a refusal leaves no half-placed install.
  binary_refuse_foreign "${install_dir}/snipset" binary_is_snipset
  ((has_shell == 0)) || binary_refuse_foreign "${install_dir}/snipset-shims" binary_is_generator
  mv -f "${stage}/snipset" "${install_dir}/snipset"
  if ((has_shell)); then
    chmod 755 "${stage}/shell/snipset-shims.sh"
    mv -f "${stage}/shell/snipset-shims.sh" "${install_dir}/snipset-shims"
  fi
}
binary_installed_version() {
  local out v
  [[ -x "${install_dir}/snipset" ]] || return 0
  out="$(binary_run_version "${install_dir}/snipset" 2>/dev/null)" || return 0
  [[ "$out" == "snipset "* ]] || return 0
  read -r _ v _ <<< "$out"
  printf '%s\n' "${v#v}"
}
binary_is_snipset() {
  local out
  out="$(binary_run_version "$1" 2>/dev/null)" || return 1
  [[ "$out" == "snipset "* ]]
}
binary_is_generator() {
  local line2=""
  { IFS= read -r _ && IFS= read -r line2; } 2>/dev/null < "$1" || true
  [[ "$line2" == '# snipset-shims:'* ]]
}
binary_check() {
  local bin="${install_dir}/snipset" gen="${install_dir}/snipset-shims" have
  if [[ ! -e "$bin" ]]; then
    report MISSING binary "$bin"
  elif [[ ! -f "$bin" || ! -x "$bin" ]]; then
    report DRIFT binary "${bin} is not executable"
  else
    have="$(binary_installed_version)"
    if [[ -z "$have" ]]; then
      report DRIFT binary "${bin} --version failed"
    elif [[ -n "$version" && "$have" != "${version#v}" ]]; then
      report DRIFT binary "${bin} is ${have}, pinned ${version#v}"
    else
      report OK binary "${bin} ${have}"
    fi
  fi
  if [[ -f "$gen" ]] && binary_is_generator "$gen"; then
    report OK snipset-shims "$gen"
  elif [[ ! -e "$gen" && ( -e "${install_dir}/.snipset-shims" || -d "$share_dir" ) ]]; then
    report MISSING snipset-shims "$gen"
  elif [[ -e "$gen" ]]; then
    report SKIP snipset-shims "${gen} is not the snipset generator"
  else
    report SKIP snipset-shims 'not installed'
  fi
}
binary_remove() {
  local bin="${install_dir}/snipset" gen="${install_dir}/snipset-shims"
  # A link may point into a package manager or a checkout that owns the real file.
  if [[ -L "$bin" ]]; then
    report KEEP binary "${bin} symlink left in place"
  elif [[ ! -e "$bin" ]]; then
    report SKIP binary "${bin} not present"
  elif [[ -f "$bin" && -x "$bin" ]] && binary_is_snipset "$bin"; then
    rm -f "$bin"
    report REMOVED binary "$bin"
  else
    report KEEP binary "${bin} does not report a snipset version"
  fi
  if [[ -L "$gen" ]]; then
    report KEEP snipset-shims "${gen} symlink left in place"
  elif [[ ! -e "$gen" ]]; then
    report SKIP snipset-shims "${gen} not present"
  elif [[ -f "$gen" ]] && binary_is_generator "$gen"; then
    rm -f "$gen"
    report REMOVED snipset-shims "$gen"
  else
    report KEEP snipset-shims "${gen} has no snipset-shims header"
  fi
}
pathenv_mark='# snipset-path (managed by snipset installer; safe to remove)'
pathenv_env_text() {
  # shellcheck disable=SC2016 # ${PATH} and $PATH are written literally into the env file
  printf '%s\n' "$pathenv_mark" \
    'case ":${PATH}:" in' \
    "  *\":${install_dir}:\"*) ;;" \
    "  *) export PATH=\"${install_dir}:\$PATH\" ;;" \
    'esac'
}
pathenv_fish_env_text() {
  printf '%s\n' "$pathenv_mark" \
    "if not contains -- \"${install_dir}\" \$PATH" \
    "    set -gx PATH \"${install_dir}\" \$PATH" \
    'end'
}
pathenv_fish_conf_text() {
  printf '%s\n' "$pathenv_mark" "source \"${share_dir}/env.fish\""
}
pathenv_source_line() {
  printf '. "%s/env" %s' "$share_dir" "$pathenv_mark"
}
pathenv_uses() {
  local login_shell="${SHELL:-}"
  [[ "${login_shell##*/}" == "$1" ]] || command -v "$1" >/dev/null 2>&1
}
pathenv_zshenv() {
  printf '%s/.zshenv' "${ZDOTDIR:-$HOME}"
}
pathenv_fish_conf() {
  printf '%s/fish/conf.d/snipset.fish' "${XDG_CONFIG_HOME:-$HOME/.config}"
}
pathenv_collect_bash() {
  pathenv_bash=("${HOME}/.bashrc" "${HOME}/.bash_profile" "${HOME}/.bash_login")
  case "$bashrc" in
    "${HOME}/.bashrc"|"${HOME}/.bash_profile"|"${HOME}/.bash_login"|"${HOME}/.profile") ;;
    *) pathenv_bash+=("$bashrc") ;;
  esac
}
# Exact comparison: $(...) strips trailing newlines, so both sides carry an x sentinel.
pathenv_same() {
  local content
  [[ -f "$1" ]] || return 1
  content="$(cat "$1"; printf x)"
  [[ "$content" == "$2" ]]
}
pathenv_line_add() {
  local line
  line="$(pathenv_source_line)"
  mkdir -p "${1%/*}"
  touch "$1"
  grep -Fqx -- "$line" "$1" || printf '\n%s\n' "$line" >> "$1"
}
# Drops each exact line and the blank line written just before it, rewriting in place to keep symlinks.
# Returns 1 when FILE holds no such line and 2 when FILE could not be rewritten.
pathenv_strip() {
  if ! { [[ -f "$1" ]] && grep -Fqx -- "$2" "$1"; }; then
    return 1
  fi
  rewrite_from "$1" env PATHENV_TARGET="$2" awk '
    $0 == ENVIRON["PATHENV_TARGET"] { if (held && prev != "") print prev; held = 0; next }
    { if (held) print prev; prev = $0; held = 1 }
    END { if (held) print prev }
  ' "$1"
}
pathenv_marked() {
  local first=""
  [[ -f "$1" ]] || return 1
  IFS= read -r first 2>/dev/null < "$1" || true
  [[ "$first" == "$pathenv_mark" ]]
}
# Writes FILE from TEXT_FN only when FILE is absent or carries the marker on line 1.
# Returns 0 when FILE holds the managed text, 1 when FILE is the user's, 2 on failure.
pathenv_put() {
  local label="$1" file="$2" fn="$3" hint="$4"
  if [[ ! -e "$file" && ! -L "$file" ]]; then
    if mkdir -p "${file%/*}" 2>/dev/null && "$fn" 2>/dev/null > "$file"; then
      return 0
    fi
    report FAIL "$label" "$file could not be written"
    return 2
  fi
  if ! pathenv_marked "$file"; then
    report KEEP "$label" "${file}: not written by the installer; add the line by hand: ${hint}"
    return 1
  fi
  if pathenv_same "$file" "$("$fn"; printf x)" || rewrite_from "$file" "$fn"; then
    return 0
  fi
  rewrite_fail "$label" "$file"
  return 2
}
pathenv_add() {
  local file env_rc=0 fish_rc=0
  ((add_path)) || return 0
  pathenv_put 'path env' "${share_dir}/env" pathenv_env_text "export PATH=\"${install_dir}:\$PATH\"" || env_rc=$?
  pathenv_put 'path env.fish' "${share_dir}/env.fish" pathenv_fish_env_text \
    "set -gx PATH \"${install_dir}\" \$PATH" || fish_rc=$?
  # A source line or fish conf would run a file the installer did not write at every login.
  if ((env_rc == 0)); then
    pathenv_line_add "${HOME}/.profile"
    pathenv_collect_bash
    for file in "${pathenv_bash[@]}"; do
      # shell_block_add creates the --bashrc file right after this, so a rerun would otherwise find it new.
      if [[ -e "$file" ]] || { [[ "$file" == "$bashrc" ]] && ((do_shell && ${has_shell:-0})); }; then
        pathenv_line_add "$file"
      fi
    done
    if pathenv_uses zsh; then
      pathenv_line_add "$(pathenv_zshenv)"
    fi
  fi
  if ((fish_rc == 0)) && pathenv_uses fish; then
    pathenv_put 'path fish' "$(pathenv_fish_conf)" pathenv_fish_conf_text "source \"${share_dir}/env.fish\"" || true
  fi
}
pathenv_check_managed() {
  if [[ ! -e "$2" ]]; then
    report MISSING "$1" "$2"
  elif pathenv_same "$2" "$3"; then
    report OK "$1" "$2"
  else
    report DRIFT "$1" "$2 differs from what the installer writes"
  fi
}
pathenv_check_line() {
  if [[ -f "$1" ]] && grep -Fqx -- "$(pathenv_source_line)" "$1"; then
    report OK 'path line' "$1"
  elif [[ -f "$1" ]] && grep -Fq 'snipset-path' "$1"; then
    report DRIFT 'path line' "$1 has an edited snipset-path line"
  else
    report MISSING 'path line' "$1"
  fi
}
pathenv_check() {
  local file
  if ! ((add_path)); then
    report SKIP path 'not requested (no --add-path)'
    return 0
  fi
  pathenv_check_managed 'path env' "${share_dir}/env" "$(pathenv_env_text; printf x)"
  pathenv_check_managed 'path env.fish' "${share_dir}/env.fish" "$(pathenv_fish_env_text; printf x)"
  pathenv_check_line "${HOME}/.profile"
  pathenv_collect_bash
  for file in "${pathenv_bash[@]}"; do
    if [[ -e "$file" ]]; then
      pathenv_check_line "$file"
    fi
  done
  if pathenv_uses zsh; then
    pathenv_check_line "$(pathenv_zshenv)"
  fi
  if pathenv_uses fish; then
    pathenv_check_managed 'path fish' "$(pathenv_fish_conf)" "$(pathenv_fish_conf_text; printf x)"
  fi
}
pathenv_remove_managed() {
  [[ -e "$2" || -L "$2" ]] || return 1
  if ! pathenv_same "$2" "$3" && ! pathenv_marked "$2"; then
    report KEEP "$1" "$2 not written by the installer; left in place"
  elif ! pathenv_same "$2" "$3"; then
    report KEEP "$1" "$2 edited; remove it by hand"
  elif rm -f -- "$2" 2>/dev/null && [[ ! -e "$2" ]]; then
    report REMOVED "$1" "$2"
  else
    report FAIL "$1" "$2 could not be removed"
    pathenv_failed=1
  fi
}
pathenv_remove() {
  local file line legacy conf rc found=0 seen=$'\n'
  pathenv_failed=0
  line="$(pathenv_source_line)"
  legacy="export PATH=\"${install_dir}:\$PATH\""
  pathenv_collect_bash
  for file in "${HOME}/.profile" "${pathenv_bash[@]}" "$(pathenv_zshenv)" "${HOME}/.zshenv"; do
    # Without ZDOTDIR ~/.zshenv is listed twice, and a failed rewrite must report once.
    [[ "$seen" != *$'\n'"$file"$'\n'* ]] || continue
    seen+="${file}"$'\n'
    rc=0
    pathenv_strip "$file" "$line" || rc=$?
    case "$rc" in
      0) report REMOVED 'path line' "$file" ;;
      2) rewrite_fail 'path line' "$file"; pathenv_failed=1 ;;
    esac
    ((rc == 1)) || found=1
  done
  # Unmarked, so it may be the user's own line rather than the old installer's.
  if [[ -f "${HOME}/.profile" ]] && grep -Fqx -- "$legacy" "${HOME}/.profile"; then
    report KEEP 'path legacy line' "${HOME}/.profile: remove it by hand if the old installer added it"
    found=1
  fi
  conf="$(pathenv_fish_conf)"
  for file in "$conf" "${HOME}/.config/fish/conf.d/snipset.fish"; do
    if pathenv_remove_managed 'path fish' "$file" "$(pathenv_fish_conf_text; printf x)"; then
      found=1
    fi
    [[ "$conf" != "${HOME}/.config/fish/conf.d/snipset.fish" ]] || break
  done
  # A line or fish file that stayed still sources these, and a missing file aborts a dash login.
  if ((pathenv_failed)); then
    for file in "${share_dir}/env" "${share_dir}/env.fish"; do
      [[ ! -e "$file" ]] || report KEEP "path ${file##*/}" "${file} is still sourced; rerun --uninstall once the failed files are writable"
    done
  else
    pathenv_remove_managed 'path env' "${share_dir}/env" "$(pathenv_env_text; printf x)" && found=1
    pathenv_remove_managed 'path env.fish' "${share_dir}/env.fish" "$(pathenv_fish_env_text; printf x)" && found=1
  fi
  ((found)) || report SKIP path 'nothing to remove'
  rmdir "$share_dir" 2>/dev/null || true
}
shell_marker='# snipset-terminal-integration (managed by snipset installer; safe to remove)'
shell_bundle_place() {
  local name
  if ((do_shell)) && ((has_shell)); then
    mkdir -p "$share_dir"
    for name in snipset.sh completion.bash tab.sh; do
      cp -f "${stage}/shell/${name}" "${share_dir}/${name}"
      chmod 755 "${share_dir}/${name}"
    done
  elif ((do_shell)); then
    note 'release predates the shell bundle; skipping shell integration'
  fi
  rm -rf "$stage"
}
# The marker and the four lines below it, exactly as shell_block_add writes them.
shell_block_lines() {
  printf '%s\n' "$shell_marker"
  # shellcheck disable=SC2016 # $PATH is written literally into .bashrc
  printf 'if ! command -v snipset >/dev/null 2>&1; then export PATH="%s:$PATH"; fi\n' "$install_dir"
  printf '[ -f "%s/snipset.sh" ] && . "%s/snipset.sh"\n' "$share_dir" "$share_dir"
  printf '[ -f "%s/completion.bash" ] && . "%s/completion.bash"\n' "$share_dir" "$share_dir"
  printf '[ -f "%s/tab.sh" ] && . "%s/tab.sh"\n' "$share_dir" "$share_dir"
}
shell_block_add() {
  if ((do_shell)) && ((has_shell)); then
    touch "$bashrc"
    if ! grep -Fq 'snipset-terminal-integration' "$bashrc"; then
      {
        printf '\n'
        shell_block_lines
      } >> "$bashrc"
    fi
  fi
}
# Reads $bashrc into shell_rc_lines and sets shell_rc_newline (1 when the file
# ends in a newline), shell_block_at (index of the first marker line, -1 when
# absent), and shell_block_exact (1 when the marker and its four lines match).
shell_block_scan() {
  local line i
  local -a want
  shell_rc_lines=()
  shell_rc_newline=1
  shell_block_at=-1
  shell_block_exact=0
  [[ -f "$bashrc" ]] || return 0
  line=""
  while IFS= read -r line; do
    shell_rc_lines+=("$line")
  done < "$bashrc"
  if [[ -n "$line" ]]; then
    shell_rc_lines+=("$line")
    shell_rc_newline=0
  fi
  for i in "${!shell_rc_lines[@]}"; do
    if [[ "${shell_rc_lines[i]}" == *snipset-terminal-integration* ]]; then
      shell_block_at=$i
      break
    fi
  done
  ((shell_block_at >= 0)) || return 0
  mapfile -t want < <(shell_block_lines)
  shell_block_exact=1
  for i in "${!want[@]}"; do
    if [[ "${shell_rc_lines[shell_block_at + i]-}" != "${want[i]}" ]]; then
      shell_block_exact=0
      return 0
    fi
  done
}
shell_check() {
  local name
  if ! ((do_shell)); then
    report SKIP shell 'not requested (--no-shell)'
    return 0
  fi
  for name in snipset.sh completion.bash tab.sh; do
    if [[ -f "${share_dir}/${name}" ]]; then
      report OK "shell ${name}" "${share_dir}/${name}"
    else
      report MISSING "shell ${name}" "${share_dir}/${name}"
    fi
  done
  shell_block_scan
  if ((shell_block_at < 0)); then
    report MISSING 'shell block' "$bashrc"
  elif ((shell_block_exact)); then
    report OK 'shell block' "$bashrc"
  else
    report DRIFT 'shell block' "${bashrc} holds the marker with other lines"
  fi
}
shell_remove() {
  local name i start end out=""
  # Without the shell bundle these names may hold the user's own files.
  if ! ((do_shell)); then
    report SKIP shell '--no-shell, nothing to remove'
    return 0
  fi
  for name in snipset.sh completion.bash tab.sh; do
    if [[ -L "${share_dir}/${name}" ]]; then
      report KEEP "shell ${name}" "${share_dir}/${name} symlink left in place"
    elif [[ -f "${share_dir}/${name}" ]]; then
      rm -f "${share_dir}/${name}"
      report REMOVED "shell ${name}" "${share_dir}/${name}"
    else
      report SKIP "shell ${name}" "${share_dir}/${name} absent"
    fi
  done
  shell_block_scan
  if ((shell_block_at < 0)); then
    report SKIP 'shell block' "none in ${bashrc}"
  elif ! ((shell_block_exact)); then
    report KEEP 'shell block' 'edited; remove it by hand'
  else
    start=$shell_block_at
    end=$((shell_block_at + 4))
    if ((start > 0)) && [[ -z "${shell_rc_lines[start - 1]}" ]]; then
      start=$((start - 1))
    fi
    for i in "${!shell_rc_lines[@]}"; do
      ((i >= start && i <= end)) && continue
      out+="${shell_rc_lines[i]}"$'\n'
    done
    if [[ -n "$out" ]] && ! ((shell_rc_newline)) && ((end < ${#shell_rc_lines[@]} - 1)); then
      out="${out%$'\n'}"
    fi
    # Write in place: a symlinked bashrc must stay a symlink into its dotfiles repo.
    if rewrite_from "$bashrc" printf '%s' "$out"; then
      report REMOVED 'shell block' "$bashrc"
    else
      rewrite_fail 'shell block' "$bashrc"
    fi
  fi
  rmdir "$share_dir" 2>/dev/null || true
}
db_init() {
  local snipset_bin="${install_dir}/snipset"
  local setup_path=(PATH="${install_dir}:${PATH}")
  if ((do_init)); then
    if [[ -n "$db" ]]; then
      if ! env "${setup_path[@]}" "$snipset_bin" --db "$db" init; then
        note "database init skipped (already exists or unreachable); run 'snipset doctor' to check"
      fi
    else
      if ! env "${setup_path[@]}" "$snipset_bin" init; then
        note "database init skipped (already exists or unreachable); run 'snipset doctor' to check"
      fi
    fi
  fi
}
db_check() {
  if [[ -z "$db" ]]; then
    report SKIP database 'default location (run snipset doctor)'
  elif [[ -e "$db" ]]; then
    report OK database "$db"
  else
    report MISSING database "$db"
  fi
}
# Never deletes anything: the database holds the user's data.
db_remove() {
  report KEEP database 'never removed by uninstall'
}
shims_generate() {
  local setup_path=(PATH="${install_dir}:${PATH}")
  local shim_out shim_rc
  if ((do_shims)) && ((has_shell)); then
    shim_out=""
    shim_rc=0
    if [[ -n "$db" ]]; then
      shim_out="$(env "${setup_path[@]}" SNIPSET_DB="$db" "${install_dir}/snipset-shims" --dir "$install_dir" 2>&1)" || shim_rc=$?
    else
      shim_out="$(env "${setup_path[@]}" "${install_dir}/snipset-shims" --dir "$install_dir" 2>&1)" || shim_rc=$?
    fi
    if ((shim_rc != 0)); then
      note "shim generation skipped; run 'snipset-shims' after fixing the database"
    elif [[ -z "$shim_out" ]]; then
      note "shim generator produced no output; run 'snipset-shims' to check triggers"
    fi
  elif ((do_shims)); then
    note "release predates the shell bundle; skipping shims"
  fi
}
shims_read_manifest() {
  local kw
  shims_names=()
  while IFS= read -r kw || [[ -n "$kw" ]]; do
    if [[ -n "$kw" ]]; then
      shims_names+=("$kw")
    fi
  done < "$1"
}
# A name with a slash, or . and .., would point outside install_dir.
shims_valid_name() {
  [[ -n "$1" && "$1" != . && "$1" != .. && "$1" != */* ]]
}
# The generator writes this on line 2; a file without it belongs to the user.
shims_is_shim() {
  local second=""
  [[ -f "$1" && ! -L "$1" ]] || return 1
  { IFS= read -r _ && IFS= read -r second; } 2>/dev/null < "$1" || [[ -n "$second" ]] || return 1
  [[ "$second" == "# snipset-shim for '"* ]]
}
shims_check() {
  local manifest="${install_dir}/.snipset-shims" kw path
  if [[ ! -f "$manifest" ]]; then
    report SKIP shims 'none generated'
    return 0
  fi
  shims_read_manifest "$manifest"
  if ((${#shims_names[@]} == 0)); then
    report SKIP shims "none listed in ${manifest}"
    return 0
  fi
  for kw in "${shims_names[@]}"; do
    path="${install_dir}/${kw}"
    if ! shims_valid_name "$kw"; then
      report DRIFT shims "${path}: listed name leaves ${install_dir}"
    elif [[ ! -e "$path" && ! -L "$path" ]]; then
      report MISSING shims "$path"
    elif shims_is_shim "$path"; then
      report OK shims "$path"
    else
      report DRIFT shims "${path}: line 2 is not a snipset-shim header"
    fi
  done
}
shims_remove() {
  local manifest="${install_dir}/.snipset-shims" kw path remaining=0
  if [[ ! -f "$manifest" ]]; then
    report SKIP shims 'none generated'
    return 0
  fi
  shims_read_manifest "$manifest"
  if ((${#shims_names[@]})); then
    for kw in "${shims_names[@]}"; do
      path="${install_dir}/${kw}"
      if ! shims_valid_name "$kw"; then
        report KEEP shims "${path}: listed name leaves ${install_dir}"
      elif [[ ! -e "$path" && ! -L "$path" ]]; then
        report SKIP shims "${path}: already absent"
      elif shims_is_shim "$path"; then
        rm -f -- "$path"
        report REMOVED shims "$path"
      else
        report KEEP shims "${path}: not a snipset-shim; remove it by hand"
      fi
    done
    for kw in "${shims_names[@]}"; do
      path="${install_dir}/${kw}"
      if [[ -e "$path" || -L "$path" ]]; then
        remaining=1
      fi
    done
  fi
  if ((remaining)); then
    report KEEP shims "${manifest}: listed names remain"
  else
    rm -f -- "$manifest"
    report REMOVED shims "$manifest"
  fi
}
mcp_cli() {
  case "$1" in
    claude|codex|gemini) printf '%s' "$1" ;;
    vscode) printf 'code' ;;
  esac
}
mcp_file() {
  case "$1" in
    opencode) printf '%s' "${HOME}/.config/opencode/opencode.json" ;;
    cursor) printf '%s' "${HOME}/.cursor/mcp.json" ;;
    vscode) printf '%s' "${XDG_CONFIG_HOME:-${HOME}/.config}/Code/User/mcp.json" ;;
  esac
}
# args.sh rejects quotes and backslashes in paths, so plain interpolation is valid JSON.
mcp_json_args() {
  if [[ -n "$db" ]]; then
    printf '"mcp","--db","%s"' "$db"
  else
    printf '"mcp"'
  fi
}
# shellcheck disable=SC2016 # "$schema" is a literal JSON key in opencode.json
mcp_file_content() {
  case "$1" in
    opencode) printf '{"$schema":"https://opencode.ai/config.json","mcp":{"snipset":{"type":"local","command":["%s",%s],"enabled":true}}}\n' "$snipset_bin" "$(mcp_json_args)" ;;
    cursor) printf '{"mcpServers":{"snipset":{"type":"stdio","command":"%s","args":[%s]}}}\n' "$snipset_bin" "$(mcp_json_args)" ;;
  esac
}
# Harness CLIs may read stdin, which under "curl | bash" is the rest of this script.
mcp_run() {
  local out rc=0
  out="$("$@" 2>&1 >/dev/null </dev/null)" || rc=$?
  mcp_err="${out%%$'\n'*}"
  [[ -n "$mcp_err" ]] || mcp_err="exit status ${rc}"
  return "$rc"
}
mcp_trim() {
  local s="${1%$'\r'}"
  s="${s#"${s%%[![:space:]]*}"}"
  printf '%s' "${s%"${s##*[![:space:]]}"}"
}
mcp_gemini_settings() { printf '%s' "${HOME}/.gemini/settings.json"; }
# Only a user-scope entry is the installer's: "remove --scope user" never touches
# another scope, and an entry in another scope can shadow the user one.
mcp_claude_probe() {
  local out line scope="" first="" cmd mine=0 bin_seen=0
  # "claude mcp get" starts the server to report its status and writes Claude's own
  # state (~/.claude, ~/.cache), so --check is not read-only for this harness.
  if ! out="$(claude mcp get snipset 2>/dev/null </dev/null)"; then
    printf 'absent'
    return 0
  fi
  while IFS= read -r line; do
    line="$(mcp_trim "$line")"
    case "$line" in
      [Ss]cope:*)
        scope="$(mcp_trim "${line#*:}")"
        case "$scope" in
          [Uu]ser*) scope=user ;;
          [Ll]ocal*) scope=local ;;
          [Pp]roject*) scope=project ;;
          *) scope="${scope%% *}" ;;
        esac
        [[ -n "$first" ]] || first="$scope" ;;
      [Cc]ommand:*)
        cmd="$(mcp_trim "${line#*:}")"
        if [[ "$cmd" == "$snipset_bin" ]]; then
          bin_seen=1
          [[ "$scope" != user ]] || mine=1
        fi
        scope="" ;;
    esac
  done <<< "$out"
  if ((mine)); then
    printf 'mine user'
  elif ((bin_seen)); then
    printf 'scoped %s' "${first:-unknown}"
  else
    printf 'foreign %s' "${first:-unknown}"
  fi
}
# The user settings file decides ownership; "gemini mcp list" merges every scope.
# Only the "snipset" object's own command counts: [^{}] keeps the match inside that
# one object, so a sibling "snipset-dev" or a nested object holding the binary does
# not make the entry ours. The value is compared as a plain string, not a pattern.
mcp_gemini_probe() {
  local settings out line text=""
  local re='"snipset"[[:space:]]*:[[:space:]]*\{[^{}]*"command"[[:space:]]*:[[:space:]]*"([^"]*)"'
  settings="$(mcp_gemini_settings)"
  [[ ! -f "$settings" ]] || text="$(cat -- "$settings")"
  if [[ "$text" == *'"snipset"'* ]]; then
    text="${text//$'\n'/ }"
    if [[ "$text" =~ $re ]] && [[ "${BASH_REMATCH[1]}" == "$snipset_bin" ]]; then
      printf 'mine'
    else
      printf 'foreign'
    fi
    return 0
  fi
  out="$(gemini mcp list 2>/dev/null </dev/null)" || out=""
  while IFS= read -r line; do
    case "$line" in
      snipset:*|*[[:space:]]snipset:*) printf 'scoped'; return 0 ;;
    esac
  done <<< "$out"
  printf 'absent'
}
# Detail for an entry the installer leaves alone because it sits in another scope.
mcp_scoped_detail() {
  case "$1" in
    claude) printf '%s entry left untouched' "$2" ;;
    gemini) printf 'snipset is registered outside %s; left untouched' "$(mcp_gemini_settings)" ;;
  esac
}
# Prints nocli, absent, other (file without snipset), mine, foreign, or scoped
# (the binary is registered in a scope the installer does not own), and for
# claude a second word naming the scope.
mcp_probe() {
  local id="$1" cli out line cmd="" text
  cli="$(mcp_cli "$id")"
  case "$id" in
    claude|codex|gemini)
      if ! command -v "$cli" >/dev/null 2>&1; then
        printf 'nocli'
        return 0
      fi ;;
  esac
  case "$id" in
    claude) mcp_claude_probe ;;
    gemini) mcp_gemini_probe ;;
    codex)
      if ! out="$(codex mcp get snipset 2>/dev/null </dev/null)"; then
        printf 'absent'
        return 0
      fi
      while IFS= read -r line; do
        line="$(mcp_trim "$line")"
        case "$line" in
          [Cc]ommand:*) cmd="$(mcp_trim "${line#*:}")"; break ;;
        esac
      done <<< "$out"
      if [[ "$cmd" == "$snipset_bin" ]]; then printf 'mine'; else printf 'foreign'; fi ;;
    *)
      if [[ ! -f "$(mcp_file "$id")" ]]; then
        printf 'absent'
        return 0
      fi
      text="$(cat -- "$(mcp_file "$id")")"
      if [[ "$text" == *"\"${snipset_bin}\""* ]]; then
        printf 'mine'
      elif [[ "$text" == *'"snipset"'* ]]; then
        printf 'foreign'
      else
        printf 'other'
      fi ;;
  esac
}
mcp_add() {
  local id="$1"
  local -a cmd=("$snipset_bin" mcp)
  [[ -z "$db" ]] || cmd+=(--db "$db")
  case "$id" in
    claude) mcp_run claude mcp add --scope user snipset -- "${cmd[@]}" ;;
    codex) mcp_run codex mcp add snipset -- "${cmd[@]}" ;;
    gemini) mcp_run gemini mcp add --scope user snipset "${cmd[@]}" ;;
    vscode) mcp_run code --add-mcp "{\"name\":\"snipset\",\"command\":\"${snipset_bin}\",\"args\":[$(mcp_json_args)]}" ;;
  esac
}
mcp_install() {
  local snipset_bin="${install_dir}/snipset"
  local id state scope file cli
  local -a ids
  read -r -a ids <<< "$mcp_list"
  for id in "${ids[@]}"; do
    cli="$(mcp_cli "$id")"
    if [[ -n "$cli" ]] && ! command -v "$cli" >/dev/null 2>&1; then
      report SKIP "$id" "${cli} not on PATH"
      continue
    fi
    read -r state scope <<< "$(mcp_probe "$id")"
    file="$(mcp_file "$id")"
    case "$id" in
      opencode|cursor)
        if [[ "$state" == absent ]]; then
          mkdir -p "$(dirname "$file")"
          mcp_file_content "$id" > "$file"
          report ADD "$id" "wrote ${file}"
          continue
        fi
        if [[ "$id" == opencode ]]; then
          note "MCP config exists; leaving $file untouched"
        else
          note "Cursor config exists; add this to mcpServers in ${file}: \"snipset\":{\"type\":\"stdio\",\"command\":\"${snipset_bin}\",\"args\":[$(mcp_json_args)]}"
        fi
        if [[ "$state" == other ]]; then
          report KEEP "$id" "${file} exists; left untouched"
        else
          report KEEP "$id" 'snipset is already registered'
        fi ;;
      *)
        # VS Code merges into its own mcp.json, so a file without snipset still gets an add.
        if [[ "$state" != absent && "$state" != other ]]; then
          report KEEP "$id" 'snipset is already registered'
        elif mcp_add "$id"; then
          report ADD "$id" 'snipset registered'
        else
          report FAIL "$id" "$mcp_err"
        fi ;;
    esac
  done
}
mcp_check() {
  local snipset_bin="${install_dir}/snipset"
  local id cli state scope
  local -a ids
  read -r -a ids <<< "$mcp_list"
  if ((${#ids[@]} == 0)); then
    report SKIP mcp 'no --with-mcp list'
    return 0
  fi
  for id in "${ids[@]}"; do
    cli="$(mcp_cli "$id")"
    if [[ -n "$cli" ]] && ! command -v "$cli" >/dev/null 2>&1; then
      report SKIP "$id" "${cli} not on PATH"
      continue
    fi
    read -r state scope <<< "$(mcp_probe "$id")"
    case "${id}:${state}" in
      *:mine) report OK "$id" "snipset points at ${snipset_bin}" ;;
      *:foreign) report KEEP "$id" 'snipset points elsewhere' ;;
      *:scoped) report KEEP "$id" "$(mcp_scoped_detail "$id" "$scope")" ;;
      opencode:other|cursor:other) report KEEP "$id" "$(mcp_file "$id") exists without snipset; not managed by the installer" ;;
      *) report MISSING "$id" 'snipset is not registered' ;;
    esac
  done
}
mcp_remove_entry() {
  local id="$1" detail="$2"
  shift 2
  if ((dry_run)); then
    printf '[DRY] mcp %s: remove %s\n' "$id" "$detail"
    return 0
  fi
  if mcp_run "$@"; then
    report REMOVED "$id" "$detail"
  else
    report FAIL "$id" "$mcp_err"
  fi
}
mcp_remove() {
  local snipset_bin="${install_dir}/snipset"
  local id state scope file text
  local -a ids
  read -r -a ids <<< "$mcp_list"
  if ((${#ids[@]} == 0)); then
    report SKIP mcp 'no --with-mcp list'
    return 0
  fi
  for id in "${ids[@]}"; do
    read -r state scope <<< "$(mcp_probe "$id")"
    file="$(mcp_file "$id")"
    case "${id}:${state}" in
      *:nocli) report SKIP "$id" "$(mcp_cli "$id") not on PATH" ;;
      claude:foreign|*:scoped) report KEEP "$id" "$(mcp_scoped_detail "$id" "$scope")" ;;
      *:foreign) report KEEP "$id" 'snipset points elsewhere' ;;
      *:absent|*:other) report SKIP "$id" 'snipset is not registered' ;;
      claude:mine) mcp_remove_entry "$id" snipset claude mcp remove --scope user snipset ;;
      codex:mine) mcp_remove_entry "$id" snipset codex mcp remove snipset ;;
      gemini:mine) mcp_remove_entry "$id" snipset gemini mcp remove --scope user snipset ;;
      vscode:mine) report KEEP "$id" "remove snipset from ${file} by hand" ;;
      *:mine)
        # The trailing x keeps the file's final newline through command substitution.
        text="$(cat -- "$file"; printf x)"
        if [[ "$text" == "$(mcp_file_content "$id"; printf x)" ]]; then
          mcp_remove_entry "$id" "$file" rm -f -- "$file"
        else
          report KEEP "$id" "${file} differs from what the installer writes; remove snipset by hand"
        fi ;;
    esac
  done
}
# Runs before the first write, so a read-only HOME gives one clear line instead of a mkdir error.
install_require_writable() {
  local dir="$install_dir"
  while [[ ! -e "$dir" ]]; do
    dir="$(dirname -- "$dir")"
  done
  [[ -d "$dir" && -w "$dir" ]] || die "${dir} is not writable"
}
# Mirrors the files pathenv_add touches; has_shell is unknown before the download, so a
# requested shell block counts as present, which is what every current release ships.
install_dry_path() {
  local file list
  local -a touched=("${HOME}/.profile")
  if ! ((add_path)); then
    printf '[DRY] path: leave %s unchanged (no --add-path)\n' "${HOME}/.profile"
    return 0
  fi
  pathenv_collect_bash
  for file in "${pathenv_bash[@]}"; do
    if [[ -e "$file" ]] || { [[ "$file" == "$bashrc" ]] && ((do_shell)); }; then
      touched+=("$file")
    fi
  done
  if pathenv_uses zsh; then
    touched+=("$(pathenv_zshenv)")
  fi
  list="${touched[0]}"
  for file in "${touched[@]:1}"; do
    list+=", ${file}"
  done
  printf '[DRY] path: write %s/env and %s/env.fish to put %s on PATH\n' "$share_dir" "$share_dir" "$install_dir"
  printf '[DRY] path: source %s/env from %s\n' "$share_dir" "$list"
  if pathenv_uses fish; then
    printf '[DRY] path: write %s\n' "$(pathenv_fish_conf)"
  fi
}
install_dry_run() {
  local id pinned="$version"
  local -a ids
  platform_require
  fetch_tools_require
  if [[ -z "$version" && -z "$from_dir" ]]; then
    fetch_resolve_version
  fi
  printf '[DRY] platform: require %s\n' "$target"
  if [[ -n "$from_dir" ]]; then
    printf '[DRY] tools: require tar; sha256sum, shasum, or openssl\n'
  else
    printf '[DRY] tools: require curl or wget; tar; sha256sum, shasum, or openssl\n'
  fi
  if [[ -n "$pinned" ]]; then
    printf '[DRY] version: use %s\n' "$pinned"
  elif [[ -n "$from_dir" ]]; then
    printf '[DRY] version: read from %s/SHA256SUMS\n' "$from_dir"
  else
    printf '[DRY] version: latest is %s\n' "$version"
  fi
  if [[ -n "$from_dir" ]]; then
    printf '[DRY] release: copy SHA256SUMS and the archive from %s\n' "$from_dir"
  else
    printf '[DRY] release: download SHA256SUMS and the %s archive from %s\n' "$target" "$base_url"
  fi
  printf '[DRY] %s\n' \
    "verify: check the archive checksum and entries" \
    "stage: extract into ${install_dir}/.snipset-stage.*" \
    "smoke: run the staged binary" \
    "binary: place ${install_dir}/snipset"
  install_dry_path
  if ((do_shell)); then
    printf '[DRY] shell bundle: copy into %s\n' "$share_dir"
    printf '[DRY] shell block: add to %s\n' "$bashrc"
  else
    printf '[DRY] shell bundle: skip %s (--no-shell)\n' "$share_dir"
    printf '[DRY] shell block: skip %s (--no-shell)\n' "$bashrc"
  fi
  if ((do_init)); then
    printf '[DRY] database: init %s\n' "${db:-the CLI default}"
  else
    printf '[DRY] database: skip (--no-init)\n'
  fi
  if ((do_shims)); then
    printf '[DRY] shims: generate in %s\n' "$install_dir"
  else
    printf '[DRY] shims: skip (--no-shims)\n'
  fi
  read -r -a ids <<< "$mcp_list"
  if ((${#ids[@]} == 0)); then
    printf '[DRY] mcp: none requested\n'
  fi
  for id in "${ids[@]}"; do
    printf '[DRY] mcp %s: register snipset\n' "$id"
  done
  printf 'dry run: nothing was written\n'
}
do_install() {
  if ((dry_run)); then
    install_dry_run
    return 0
  fi
  platform_require
  fetch_tools_require
  install_require_writable
  fetch_resolve_version
  tmp="$(mktemp -d "${TMPDIR:-/tmp}/snipset-install.XXXXXX")"
  trap 'rm -rf "$tmp" "${stage:-}"' EXIT
  fetch_release "$tmp"
  binary_verify "$tmp"
  binary_stage "$tmp"
  binary_smoke
  binary_place
  pathenv_add
  shell_bundle_place
  shell_block_add
  db_init
  shims_generate
  mcp_install
  printf 'Installed snipset %s to %s\n' "$version" "${install_dir}/snipset"
  ((n_fail == 0)) || exit 1
}
do_check() {
  binary_check
  shell_check
  db_check
  shims_check
  pathenv_check
  mcp_check
  if ((n_drift)); then
    printf 'check: DRIFT (%d items)\n' "$n_drift"
    return 1
  fi
  printf 'check: CURRENT\n'
}
do_update() {
  local have
  if ((dry_run)); then
    do_install
    return 0
  fi
  platform_require
  fetch_tools_require
  fetch_resolve_version
  have="$(binary_installed_version)"
  if [[ -n "$have" && "$have" == "${version#v}" ]]; then
    report OK update "snipset ${have} is current"
    return 0
  fi
  do_install
}
do_uninstall() {
  # The remove functions delete for real, so there is nothing safe to preview.
  if ((dry_run)); then
    die "--dry-run cannot preview --uninstall; run --check to see what is installed" 2
  fi
  mcp_remove
  shims_remove
  db_remove
  shell_remove
  pathenv_remove
  binary_remove
  printf 'uninstall: removed %d, kept %d\n' "$n_removed" "$n_kept"
  ((n_fail == 0)) || exit 1
}
parse_args "$@"
case "$mode" in
  install) do_install ;;
  check) do_check ;;
  update) do_update ;;
  uninstall) do_uninstall ;;
esac
